import sys
from collections import defaultdict

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        n = int(input[ptr])
        ptr += 1
        a = list(map(int, input[ptr:ptr + n]))
        ptr += n
        b = list(map(int, input[ptr:ptr + n]))
        ptr += n

        freq_a = defaultdict(int)
        freq_b = defaultdict(int)
        for num in a:
            freq_a[num] += 1
        for num in b:
            freq_b[num] += 1

        possible = True
        for num in freq_a:
            if freq_b[num] < freq_a[num]:
                possible = False
                break
            freq_b[num] -= freq_a[num]

        if not possible:
            print("NO")
            continue

        temp_b = []
        for num in freq_b:
            temp_b.extend([num] * freq_b[num])

        for num in temp_b:
            x = num
            found = False
            for a_num in a:
                if a_num == x:
                    found = True
                    break
                if x % 2 == 0 and a_num == x // 2:
                    found = True
                    break
                if x * 2 == a_num:
                    found = True
                    break
            if not found:
                possible = False
                break

        if possible:
            print("YES")
        else:
            print("NO")

solve()
